package glitch

import data.glitch_lib

# CWE-326: Inadequate Encryption Strength

# Set of weak cryptographic indicators
weak_algorithms := {"DES", "3DES", "RC4", "Blowfish", "IDEA", "MD5", "SHA1", "ECB", "SSLv2", "SSLv3", "TLS 1.0", "TLS 1.1", "Basic", "HTTP"}
weak_curves := {"secp192r1", "sect163k1", "secp160k1"}
insufficient_key_sizes := {512, 64, 128}
deprecated_policies := {"ELBSecurityPolicy-2016-08"}

# Helper to check if a string value contains weak indicators
check_weak_string(str_val) {
    # Check for weak algorithms (case insensitive)
    regex.match("(?i).*(DES|3DES|RC4|Blowfish|IDEA|MD5|SHA1|ECB|SSLv2|SSLv3|TLS\\s*1\\.0|TLS\\s*1\\.1|Basic|HTTP).*", str_val)
}

# Helper to check for insufficient key lengths in string values
check_insufficient_key_length(str_val) {
    # Check for key sizes like 1024, 512, 64, 128 bits
    regex.match("(?i).*(1024|512|64|128)\\s*(bits?|bit)?", str_val)
}

# Helper to check for weak curves
check_weak_curve(str_val) {
    regex.match("(?i).*(secp192r1|sect163k1|secp160k1).*", str_val)
}

# Check for weak encryption configuration in attributes
check_weak_encryption_attribute(attr) {
    # Direct string match for weak algorithms or protocols
    attr.value.ir_type == "String"
    check_weak_string(attr.value.value)
} else {
    # Check for insufficient integer key sizes
    attr.value.ir_type == "Integer"
    insufficient_key_sizes[_] == attr.value.value
} else {
    # Check for weak key curves in string format
    attr.value.ir_type == "String"
    check_weak_curve(attr.value.value)
}

# Check for insecure state flags (e.g., encryption disabled)
check_insecure_state(attr) {
    attr.value.ir_type == "Boolean"
    attr.name == "encrypted"
    attr.value.value == false
} else {
    attr.value.ir_type == "Boolean"
    attr.name == "enabled"
    attr.value.value == false
}

# Check for hardcoded IVs or salts (static randomness)
check_static_randomness(attr) {
    attr.value.ir_type == "String"
    attr.name == "iv"
    regex.match("^0+$", attr.value.value)
} else {
    attr.value.ir_type == "String"
    attr.name == "salt"
    regex.match("^0+$", attr.value.value)
} else {
    # Check for hardcoded PSKs (plaintext keys)
    attr.value.ir_type == "String"
    regex.match("(?i).*(pre[_-]?shared|psk|secret|key).*", attr.name)
    length(attr.value.value) > 0
}

# Main rule for detecting weak encryption in atomic units (resources)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for weak encryption attributes or insecure states
    (check_weak_encryption_attribute(attr) OR check_insecure_state(attr) OR check_static_randomness(attr))

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cryptographic algorithms, insufficient key lengths, or insecure configurations detected. (CWE-326)"
    }
}

# Secondary rule for checking variables (potential hardcoded keys or weak configs)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    variables := glitch_lib.all_variables(parent)
    var := variables[_]

    # Check variable values for weak encryption indicators
    (check_weak_encryption_attribute(var) OR check_static_randomness(var))

    result := {
        "type": "sec_weak_crypt",
        "element": var,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Variable contains weak cryptographic configuration or hardcoded secrets. (CWE-326)"
    }
}

