package glitch

import data.glitch_lib

# CWE-326: Inadequate Encryption Strength

# Weak cryptographic indicators
weak_algorithms := {"DES", "3DES", "RC4", "Blowfish", "IDEA", "MD5", "SHA1", "SHA-1", "ECB", "SSLv2", "SSLv3", "TLS 1.0", "TLS 1.1", "Basic", "HTTP", "md5_crypt"}
weak_curves := {"secp192r1", "sect163k1", "secp160k1"}
insufficient_key_sizes := {512, 1024, 64, 128}
deprecated_policies := {"ELBSecurityPolicy-2016-08"}

# Helper to check if a string contains weak indicators (case-insensitive regex)
contains_weak_string(str_val) {
    regex.match("(?i).*(DES|3DES|RC4|Blowfish|IDEA|MD5|SHA1|SHA-1|ECB|SSLv2|SSLv3|TLS\\s*1\\.0|TLS\\s*1\\.1|Basic|HTTP|md5_crypt).*", str_val)
}

# Helper to check for insufficient key lengths in string values
contains_insufficient_key_length(str_val) {
    regex.match("(?i).*(1024|512|64|128)\\s*(bits?|bit)?", str_val)
}

# Helper to check for weak curves
contains_weak_curve(str_val) {
    regex.match("(?i).*(secp192r1|sect163k1|secp160k1).*", str_val)
}

# Traverse a complex value (Hash or Array) and check for weak encryption patterns
check_complex_value(val) {
    val.ir_type == "Hash"
    check_hash_weakness(val.value)
} else {
    val.ir_type == "Array"
    check_array_weakness(val.value)
}

check_hash_weakness(pairs) {
    # Check keys or values in a hash for weak indicators
    pair := pairs[_]
    # Check key (often attribute names)
    pair.key.ir_type == "String"
    contains_weak_string(pair.key.value)
} else {
    pair := pairs[_]
    # Check value
    check_value_weakness(pair.value)
}

check_array_weakness(arr) {
    # Check elements in an array for weak indicators
    elem := arr[_]
    check_value_weakness(elem)
}

check_value_weakness(val) {
    # Check primitive values within complex structures
    val.ir_type == "String"
    contains_weak_string(val.value)
} else {
    val.ir_type == "Integer"
    insufficient_key_sizes[_] == val.value
} else {
    val.ir_type == "String"
    contains_insufficient_key_length(val.value)
} else {
    val.ir_type == "String"
    contains_weak_curve(val.value)
} else {
    # Recursively check complex values
    val.ir_type == "Hash"
    check_hash_weakness(val.value)
} else {
    val.ir_type == "Array"
    check_array_weakness(val.value)
}

# Check an attribute for weak encryption configuration
check_weak_encryption_attribute(attr) {
    # Direct string match for weak algorithms or protocols
    attr.value.ir_type == "String"
    contains_weak_string(attr.value.value)
} else {
    # Check for insufficient integer key sizes
    attr.value.ir_type == "Integer"
    insufficient_key_sizes[_] == attr.value.value
} else {
    # Check for weak key curves in string format
    attr.value.ir_type == "String"
    contains_weak_curve(attr.value.value)
} else {
    # Check complex values (Hash/Array)
    check_complex_value(attr.value)
}

# Check for insecure state flags (e.g., encryption disabled)
check_insecure_state(attr) {
    attr.value.ir_type == "Boolean"
    attr.name == "encrypted"
    attr.value.value == false
} else {
    attr.value.ir_type == "Boolean"
    attr.name == "enabled"
    attr.value.value == false
} else {
    # Check for 'false' in string format (e.g., Ansible)
    attr.value.ir_type == "String"
